GR = '#3f9a5a'; OR = '#f08a2c'; BLU = '#4f9be8'

def P(cx, by, cls='f-acc2', s=1.0, hair='f-black'): return mp(cx, by, cls, s, hair)
def Wm(cx, by, cls='f-acc', s=1.0):
    return f'<g transform="translate({cx} {by}) scale({s})"><path d="M-14 -38 q-5 -27 14 -27 q19 0 14 27 q-2 -14 -14 -14 q-12 0 -14 14z" class="f-black"/></g>' + mp(cx, by, cls, s)
def arr(x1, y1, x2, y2, cls='s-acc2', w=4, h=7):
    a = math.atan2(y2 - y1, x2 - x1); p = []
    for d in (2.5, -2.5):
        p.append(f'M{x2:.1f} {y2:.1f} L{x2 - h*math.cos(a + d/3.2*1.0) :.1f} {y2 - h*math.sin(a + d/3.2):.1f}')
    return f'<path d="M{x1} {y1} L{x2} {y2} {p[0]} {p[1]}" class="{cls}" stroke-width="{w}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
def bub(x, y, w, h, cls=None, tx=None, flip=False):
    c = cls or W; c = f'class="{c}"' if cls else c
    tx = tx if tx is not None else (x + w - 22 if flip else x + 12)
    return f'<path d="M{tx} {y+h-2} l{-4 if flip else 4} 12 l{12 if not flip else -12} -12z" {c}/><rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{min(h, w)/3.2:.1f}" {c}/><rect x="{tx+ (1 if not flip else -13)}" y="{y+h-5}" width="13" height="4" {c.replace("s-soft", "")} stroke="none"/>'
def clk(cx, cy, r, ha, ma, ring='f-acc2', hc='s-ink', mc='s-ink'):
    hx, hy = cx + r*.45*math.sin(math.radians(ha)), cy - r*.45*math.cos(math.radians(ha))
    mx, my = cx + r*.68*math.sin(math.radians(ma)), cy - r*.68*math.cos(math.radians(ma))
    return (f'<circle cx="{cx}" cy="{cy}" r="{r}" class="{ring}"/><circle cx="{cx}" cy="{cy}" r="{r*.8:.1f}" class="f-paper"/>'
            f'<path d="M{cx} {cy} L{hx:.1f} {hy:.1f}" class="{hc}" stroke-width="{max(2.5, r*.14):.1f}" stroke-linecap="round"/><path d="M{cx} {cy} L{mx:.1f} {my:.1f}" class="{mc}" stroke-width="{max(2, r*.1):.1f}" stroke-linecap="round"/><circle cx="{cx}" cy="{cy}" r="{max(2, r*.09):.1f}" class="f-ink"/>')
def cal(x=12, y=14, w=72, h=72, head='f-acc'):
    return (f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="6" {W}/><path d="M{x} {y+6} a6 6 0 0 1 6 -6 h{w-12} a6 6 0 0 1 6 6 v10 h-{w}z" class="{head}"/>'
            f'<rect x="{x+w*.24:.0f}" y="{y-6}" width="5" height="13" rx="2.5" class="f-ink"/><rect x="{x+w*.7:.0f}" y="{y-6}" width="5" height="13" rx="2.5" class="f-ink"/>')
def spark(cx, cy, r=8, cls='f-gold'):
    k = r * .28
    return f'<path d="M{cx} {cy-r} L{cx+k:.1f} {cy-k:.1f} L{cx+r} {cy} L{cx+k:.1f} {cy+k:.1f} L{cx} {cy+r} L{cx-k:.1f} {cy+k:.1f} L{cx-r} {cy} L{cx-k:.1f} {cy-k:.1f}Z" class="{cls}"/>'
def heart(cx, cy, s=1.0, cls='f-acc'):
    return f'<path transform="translate({cx} {cy}) scale({s})" d="M0 8 C-14 -2 -10 -12 -4 -12 C-1 -12 0 -9 0 -8 C0 -9 1 -12 4 -12 C10 -12 14 -2 0 8Z" class="{cls}"/>'
def chk(cx, cy, s=1.0, col=GR, w=5):
    return f'<path transform="translate({cx} {cy}) scale({s})" d="M-9 0 L-3 7 L10 -8" stroke="{col}" stroke-width="{w}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
def xm(cx, cy, s=1.0, cls='s-acc', w=5):
    return f'<path transform="translate({cx} {cy}) scale({s})" d="M-8 -8 L8 8 M8 -8 L-8 8" class="{cls}" stroke-width="{w}" stroke-linecap="round"/>'
def star(cx, cy, r=12, cls='f-gold'):
    pts = []
    for i in range(10):
        rr = r if i % 2 == 0 else r * .45; a = math.radians(-90 + i * 36)
        pts.append(f'{cx + rr*math.cos(a):.1f},{cy + rr*math.sin(a):.1f}')
    return f'<polygon points="{" ".join(pts)}" class="{cls}"/>'
def tagp(n, extra=''):
    return ('<g transform="rotate(-12 48 50)"><path d="M10 30 h52 l22 20 l-22 20 h-52z" class="f-gold"/><circle cx="70" cy="50" r="4.500" class="f-paper"/>'
            f'<text x="38" y="58" text-anchor="middle" class="t b f-black" font-size="{22 if n < 3 else 19}">{"¥" * n}</text></g>' + extra)
def box(x=52, y=42, s=36, cls='f-gold'):
    return f'<rect x="{x}" y="{y}" width="{s}" height="{s}" rx="3" class="{cls}"/><path d="M{x} {y+s*.3:.0f} h{s}" class="s-black" stroke-width="2" opacity=".25"/>'
def ball(cx, cy, r=10): return f'<circle cx="{cx}" cy="{cy}" r="{r}" class="f-acc"/><circle cx="{cx-r*.3:.1f}" cy="{cy-r*.3:.1f}" r="{r*.25:.1f}" class="f-white" opacity=".5"/>'
def days(target):
    o = ''
    for i in range(5):
        x = 5 + i * 18
        o += f'<rect x="{x}" y="34" width="14" height="24" rx="3" class="{"f-acc" if i == target else "f-soft2"}"/>'
        if i == 2: o += f'<rect x="{x-3}" y="30" width="20" height="32" rx="5" fill="none" class="s-ink" stroke-width="2.500"/>'
    o += '<path d="M48 66 v8" class="s-ink" stroke-width="2.500" stroke-linecap="round"/><circle cx="48" cy="80" r="3.500" class="f-ink"/>'
    if target != 2: o += arr(48, 20, 12 + target * 18, 20, 's-acc', 4, 7)
    return o
def years(target):
    o = ''
    for i in range(3):
        x = 5 + i * 30
        o += f'<rect x="{x}" y="26" width="26" height="46" rx="4" class="{"f-acc2" if i == target else "f-soft2"}"/>'
        o += ''.join(f'<circle cx="{x + 7 + (j % 2) * 12}" cy="{40 + (j // 2) * 16}" r="3.600" fill="{c}"/>' for j, c in enumerate(('#f3a9bb', '#e9b23c', '#c4432f', '#bfe0fb')))
        if i == 1: o += f'<rect x="{x-3}" y="22" width="32" height="54" rx="6" fill="none" class="s-ink" stroke-width="2.500"/>'
    if target != 1: o += arr(48, 12, 18 + target * 30, 12, 's-acc', 4, 7)
    return o
